#include <stdio.h>
#include <stdlib.h>

#include <music/include/MusicRanging.h>
#include <testsupport/include/test_utils.h>

#include "unity.h"

#define SHOW_RESULTS	1

using namespace ranging;

static const float DISTANCE_TOLERANCE = 0.08f; /* Tolerance of xx centimeters */

static void ref_test(const MatrixCmpl &H_est, const float distance_ref) {
	MusicRanging mr;
	msize_t L = 40;
	float dist_est = 0.0f;
        float likeliness = 0.0f;

#if GLOBAL_DEF_EVD_TYPE && !TEST_IMPL_SHOW_COMPARAISON
        {
        MatrixCmpl eigenvects(L, std::min(mr.config().MethodSubspaceSep, L), MATRIX_CLEAR_DATA);
	MatrixF EVs(1, std::min(mr.config().MethodSubspaceSep, L), MATRIX_UNINIT_DATA);
	mr.calculate(CHANNEL_DISTANCE, L, H_est, dist_est, likeliness, eigenvects, EVs, global_evd_type);
        
        TEST_ASSERT_FLOAT_WITHIN(DISTANCE_TOLERANCE, distance_ref, dist_est);
        }
#else
/* Default case */
	{
		MatrixCmpl eigenvects(L, L, MATRIX_CLEAR_DATA);
		MatrixF EVs(1, L, MATRIX_UNINIT_DATA);
		mr.calculate(CHANNEL_DISTANCE, L, H_est, dist_est, likeliness, eigenvects, EVs, ALGO_TYPE_EVD);
		if (SHOW_RESULTS) printf("EVD        dist: %f\n",dist_est);
		TEST_ASSERT_FLOAT_WITHIN(DISTANCE_TOLERANCE, distance_ref, dist_est);
	}
	{
		MatrixCmpl eigenvects(L, L, MATRIX_CLEAR_DATA);
		MatrixF EVs(1, L, MATRIX_UNINIT_DATA);
		mr.calculate(CHANNEL_DISTANCE, L, H_est, dist_est, likeliness, eigenvects, EVs, ALGO_TYPE_EIGEN_SAES);
		if (SHOW_RESULTS) printf("EIGEN_SAES dist: %f\n",dist_est);
		TEST_ASSERT_FLOAT_WITHIN(DISTANCE_TOLERANCE, distance_ref, dist_est);
	}
#endif
}

